#include "stdafx.h"#include "Pool.h"#include <rsuErr.h>KPool::KPool(): m_Count(0), m_ActiveI( 0 ){  ZeroMemory( m_Ctrls, sizeof(m_Ctrls) );}void KPool::Register( IPool *pCB ){  ASS( m_Count<_countof(m_Ctrls) );  if( m_Count==_countof(m_Ctrls) )    return;  m_Ctrls[m_Count].pCB = pCB;  m_Ctrls[m_Count].pName = pCB->GetName();  ++m_Count;}bool KPool::GetFirstACSObject(){  m_ActiveI = 0;  m_nAcsFindObjStep = 0;  m_nAcsFindIOStep = 0;  if( !m_Count )    return false;  return m_Ctrls[m_ActiveI].pCB->GetFirstACSObject();}bool KPool::GetNextACSObject( void ** pData, char *Name, size_t sn, char *Data, size_t sd ){  LPCSTR pszName = NULL;  int nFcsNumb = 0;  if( !m_Count )    return false;  if( !m_nAcsFindObjStep )  {    bool r = m_Ctrls[m_ActiveI].pCB->GetNextACSObject( pData, Name, sn, Data, sd );    if( !r )    {      while( 1 )      {        ++m_ActiveI;        if( m_ActiveI>=m_Count )          break;        r = m_Ctrls[m_ActiveI].pCB->GetFirstACSObject();        if( !r )          continue;        r = m_Ctrls[m_ActiveI].pCB->GetNextACSObject( pData, Name, sn, Data, sd );        if( !r )          continue;        break;      }    }    if( r )      return true;  }  return false;}bool KPool::ShowACSObject( void * pInfo, HWND hMainWnd, char * Name, void * pData ){  for( int i=0; i<m_Count; ++i )  {    m_Ctrls[i].pCB->ShowACSObject( hMainWnd, Name, pData );  }  return true;}